export const toModelMessagesEffect = Effect.fnUntraced(function* (input: WithParts[], model: Provider.Model, options?: {
    stripMedia?: boolean;
    toolOutputMaxChars?: number;
}) {
    const result: UIMessage[] = [];
    const toolNames = new Set<string>();
    const supportsMediaInToolResult = (attachment: {
        mime: string;
    }) => {
        if (model.api.npm === "@ai-sdk/anthropic")
            return true;
        if (model.api.npm === "@ai-sdk/openai")
            return true;
        if (model.api.npm === "@ai-sdk/amazon-bedrock/mantle")
            return true;
        if (model.api.npm === "@ai-sdk/amazon-bedrock")
            return attachment.mime.startsWith("image/");
        if (model.api.npm === "@ai-sdk/xai")
            return attachment.mime.startsWith("image/");
        if (model.api.npm === "@ai-sdk/google-vertex/anthropic")
            return true;
        if (model.api.npm === "@ai-sdk/google") {
            const id = model.api.id.toLowerCase();
            return id.includes("gemini-3") && !id.includes("gemini-2");
        }
        return false;
    };
    const toModelOutput = (options: {
        toolCallId: string;
        input: unknown;
        output: unknown;
    }) => {
        const output = options.output;
        if (typeof output === "string") {
            return { type: "text", value: output };
        }
        if (typeof output === "object") {
            const outputObject = output as {
                text: string;
                attachments?: Array<{
                    mime: string;
                    url: string;
                }>;
            };
            const attachments = (outputObject.attachments ?? []).filter((attachment) => {
                return attachment.url.startsWith("data:") && attachment.url.includes(",");
            });
            return {
                type: "content",
                value: [
                    ...(outputObject.text ? [{ type: "text", text: outputObject.text }] : []),
                    ...attachments.map((attachment) => ({
                        type: "media",
                        mediaType: attachment.mime,
                        data: iife(() => {
                            const commaIndex = attachment.url.indexOf(",");
                            return commaIndex === -1 ? attachment.url : attachment.url.slice(commaIndex + 1);
                        }),
                    })),
                ],
            };
        }
        return { type: "json", value: output as never };
    };
    for (const msg of input) {
        if (msg.parts.length === 0)
            continue;
        if (msg.info.role === "user") {
            const userMessage: UIMessage = {
                id: msg.info.id,
                role: "user",
                parts: [],
            };
            for (const part of msg.parts) {
                if (part.type === "text" && !part.ignored && part.text !== "")
                    userMessage.parts.push({
                        type: "text",
                        text: part.text,
                    });
                if (part.type === "file" && part.mime !== "text/plain" && part.mime !== "application/x-directory") {
                    if (options?.stripMedia && isMedia(part.mime)) {
                        userMessage.parts.push({
                            type: "text",
                            text: `[Attached ${part.mime}: ${part.filename ?? "file"}]`,
                        });
                    }
                    else {
                        userMessage.parts.push({
                            type: "file",
                            url: part.url,
                            mediaType: part.mime,
                            filename: part.filename,
                        });
                    }
                }
                if (part.type === "compaction") {
                    userMessage.parts.push({
                        type: "text",
                        text: "What did we do so far?",
                    });
                }
                if (part.type === "subtask") {
                    userMessage.parts.push({
                        type: "text",
                        text: "The following tool was executed by the user",
                    });
                }
            }
            if (userMessage.parts.length > 0)
                result.push(userMessage);
        }
        if (msg.info.role === "assistant") {
            const differentModel = `${model.providerID}/${model.id}` !== `${msg.info.providerID}/${msg.info.modelID}`;
            const media: Array<{
                mime: string;
                url: string;
                filename?: string;
            }> = [];
            if (msg.info.error &&
                !(AbortedError.isInstance(msg.info.error) &&
                    msg.parts.some((part) => part.type !== "step-start" && part.type !== "reasoning"))) {
                continue;
            }
            const assistantMessage: UIMessage = {
                id: msg.info.id,
                role: "assistant",
                parts: [],
            };
            const hasSignedReasoning = msg.parts.some((part) => {
                if (part.type !== "reasoning")
                    return false;
                return part.metadata?.anthropic?.signature != null;
            });
            for (const part of msg.parts) {
                if (part.type === "text") {
                    const text = part.text === "" && hasSignedReasoning ? " " : part.text;
                    assistantMessage.parts.push({
                        type: "text",
                        text,
                        ...(differentModel ? {} : { providerMetadata: part.metadata }),
                    });
                }
                if (part.type === "step-start")
                    assistantMessage.parts.push({
                        type: "step-start",
                    });
                if (part.type === "tool") {
                    toolNames.add(part.tool);
                    if (part.state.status === "completed") {
                        const outputText = part.state.time.compacted
                            ? "[Old tool result content cleared]"
                            : truncateToolOutput(part.state.output, options?.toolOutputMaxChars);
                        const attachments = part.state.time.compacted || options?.stripMedia ? [] : (part.state.attachments ?? []);
                        const mediaAttachments = attachments.filter((a) => isMedia(a.mime));
                        const extractedMedia = mediaAttachments.filter((a) => !supportsMediaInToolResult(a));
                        if (extractedMedia.length > 0) {
                            media.push(...extractedMedia);
                        }
                        const finalAttachments = attachments.filter((a) => !isMedia(a.mime) || supportsMediaInToolResult(a));
                        const output = finalAttachments.length > 0
                            ? {
                                text: outputText,
                                attachments: finalAttachments,
                            }
                            : outputText;
                        assistantMessage.parts.push({
                            type: ("tool-" + part.tool) as `tool-${string}`,
                            state: "output-available",
                            toolCallId: part.callID,
                            input: part.state.input,
                            output,
                            ...(part.metadata?.providerExecuted ? { providerExecuted: true } : {}),
                            ...(differentModel ? {} : { callProviderMetadata: providerMeta(part.metadata) }),
                        });
                    }
                    if (part.state.status === "error") {
                        const output = part.state.metadata?.interrupted === true ? part.state.metadata.output : undefined;
                        if (typeof output === "string") {
                            assistantMessage.parts.push({
                                type: ("tool-" + part.tool) as `tool-${string}`,
                                state: "output-available",
                                toolCallId: part.callID,
                                input: part.state.input,
                                output,
                                ...(part.metadata?.providerExecuted ? { providerExecuted: true } : {}),
                                ...(differentModel ? {} : { callProviderMetadata: providerMeta(part.metadata) }),
                            });
                        }
                        else {
                            assistantMessage.parts.push({
                                type: ("tool-" + part.tool) as `tool-${string}`,
                                state: "output-error",
                                toolCallId: part.callID,
                                input: part.state.input,
                                errorText: part.state.error,
                                ...(part.metadata?.providerExecuted ? { providerExecuted: true } : {}),
                                ...(differentModel ? {} : { callProviderMetadata: providerMeta(part.metadata) }),
                            });
                        }
                    }
                    if (part.state.status === "pending" || part.state.status === "running")
                        assistantMessage.parts.push({
                            type: ("tool-" + part.tool) as `tool-${string}`,
                            state: "output-error",
                            toolCallId: part.callID,
                            input: part.state.input,
                            errorText: "[Tool execution was interrupted]",
                            ...(part.metadata?.providerExecuted ? { providerExecuted: true } : {}),
                            ...(differentModel ? {} : { callProviderMetadata: providerMeta(part.metadata) }),
                        });
                }
                if (part.type === "reasoning") {
                    if (differentModel) {
                        if (part.text.trim().length > 0)
                            assistantMessage.parts.push({
                                type: "text",
                                text: part.text,
                            });
                        continue;
                    }
                    assistantMessage.parts.push({
                        type: "reasoning",
                        text: part.text,
                        providerMetadata: part.metadata,
                    });
                }
            }
            if (assistantMessage.parts.length > 0) {
                result.push(assistantMessage);
                if (media.length > 0) {
                    result.push({
                        id: MessageID.ascending(),
                        role: "user",
                        parts: [
                            {
                                type: "text" as const,
                                text: SYNTHETIC_ATTACHMENT_PROMPT,
                            },
                            ...media.map((attachment) => ({
                                type: "file" as const,
                                url: attachment.url,
                                mediaType: attachment.mime,
                                filename: attachment.filename,
                            })),
                        ],
                    });
                }
            }
        }
    }
    const tools = Object.fromEntries(Array.from(toolNames).map((toolName) => [toolName, { toModelOutput }]));
    return yield* Effect.promise(() => convertToModelMessages(result.filter((msg) => msg.parts.some((part) => part.type !== "step-start")), {
        tools,
    }));
});
